app = AgentFunctionApp(agents=[content_agent])

@app.orchestration_trigger(context_name='context')
def content_approval(context: df.DurableOrchestrationContext):
    writer = app.get_agent(context, 'ContentGenerationAgent')
    draft = yield writer.run(messages=f'Write about {context.get_input()}')
    approval = context.wait_for_external_event('ApprovalDecision')
    timeout = context.create_timer(context.current_utc_datetime + timedelta(hours=24))
    winner = yield context.task_any([approval, timeout])
    if winner == approval:
        timeout.cancel()
        return (yield context.call_activity('publish', draft))
    return (yield context.call_activity('escalate', draft))
